mapper.select:
SELECT r.*, (SELECT COUNT(*) FROM sys_role_permission rp INNER JOIN sys_permission perm ON perm.id = rp.permission_id AND perm.is_deleted = 0 WHERE rp.role_id = r.id AND rp.is_deleted = 0 AND perm.type IN ('menu', 'button')) AS permission_count FROM sys_role r WHERE r.is_deleted = 0 AND r.tenant_id = #{tenantId}
AND (r.name LIKE CONCAT('%', #{req.keyword}, '%') OR r.code LIKE CONCAT('%', #{req.keyword}, '%'))
AND r.data_scope = #{req.dataScope}
ORDER BY permission_count ${req.safeOrderDirection()}
ORDER BY r.${req.safeOrderBy()} ${req.safeOrderDirection()}
ORDER BY r.sort ASC

SELECT r.*
FROM sys_role r
         INNER JOIN sys_user_role ur
                    ON ur.role_id = r.id
                        AND ur.is_deleted = 0
                        AND ur.user_id = #{userId}
                        AND ur.tenant_id = #{tenantId}
WHERE r.is_deleted = 0
  AND r.tenant_id = #{tenantId}
ORDER BY r.sort ASC
